handler_v2.go L1914-1921:
	shardsNum := int32(ShardNumDefault)
	if shardsNumStr, ok := httpReq.Params["shardsNum"]; ok {
		if shards, err := strconv.ParseInt(fmt.Sprintf("%v", shardsNumStr), 10, 64); err == nil {
			shardsNum = int32(shards)
		}
	}
	req.ShardsNum = shardsNum
——REST 只接受 params.shardsNum；顶层 shardsNum 不在 CollectionReq 结构体中被丢弃。校验侧 task.go L393: if t.ShardsNum > Params.ProxyCfg.MaxShardNum.GetAsInt32() { return fmt.Errorf("maximum shards's number should be limited to %d", ...) } 存在且有效（对该路径传参的请求会拒绝）。
